class Terminal(Featurizer):

    def get_observation_space(self, task):
        return {}

    def clear(self):
        # for windows
        if os.name == 'nt':
            _ = os.system('cls')
            # for mac and linux(here, os.name is 'posix')
        else:
            _ = os.system('clear')

    def featurize(self, task):
        self.clear()
        print("\r")
        print(task.world.render(perspective=task.perspective))

        print('-' * 80)
        print('Wiki')
        print(task.get_wiki())
        print('Task:')
        print(task.get_task())
        print('Inventory:')
        print(task.get_inv())

        print('-' * 80)
        print('Last turn:')
        print('-' * 80)
        if task.history:
            for event in task.history[-1]:
                print(event)

        print('-' * 80)
        print('Monsters:')
        print('-' * 80)
        for m in task.world.monsters:
            print('{}: {}'.format(m.char, m))
            print(m.describe())
            print()

        print('-' * 80)
        print('Items:')
        print('-' * 80)
        for m in task.world.items:
            print('{}: {}'.format(m.char, m))
            print(m.describe())
            print()

        print()
        pprint(M.Player.keymap)
        return {}


